/* prog22_snake_camel_convert.c
 *
 * Re‑implementation of the original binary's observable behaviour:
 *   prog22_snake_camel_convert <mode> <string>
 *
 *   mode  = "to_camel"  – convert snake_case to camelCase
 *   mode  = "to_snake"  – convert camelCase to snake_case
 *
 * Prints "USAGE" if the argument count is wrong,
 * "INVALID_MODE" for an unknown mode,
 * otherwise prints the converted string.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 1024

static char out_buf[OUT_BUF_SIZE];

static void to_camel(const char *src)
{
    size_t out = 0;
    int capitalize = 0;

    for ( ; *src && out + 1 < OUT_BUF_SIZE; ++src )
    {
        if (*src == '_')
        {
            capitalize = 1;               /* next character becomes upper case */
        }
        else
        {
            char ch = *src;
            if (capitalize)
            {
                ch = (char)toupper((unsigned char)ch);
                capitalize = 0;
            }
            out_buf[out++] = ch;
        }
    }
    out_buf[out] = '\0';
}

static void to_snake(const char *src)
{
    size_t out = 0;
    int first = 1;                       /* true while we are at the first character */

    for ( ; *src && out + 2 < OUT_BUF_SIZE; ++src )
    {
        unsigned char ch = (unsigned char)*src;
        if (isupper(ch))
        {
            if (!first)                 /* prepend '_' except before the first word */
                out_buf[out++] = '_';
            out_buf[out++] = (char)tolower(ch);
        }
        else
        {
            out_buf[out++] = (char)ch;
        }
        first = 0;
    }
    out_buf[out] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    if (strcmp(argv[1], "to_camel") == 0) {
        to_camel(argv[2]);
        puts(out_buf);
    }
    else if (strcmp(argv[1], "to_snake") == 0) {
        to_snake(argv[2]);
        puts(out_buf);
    }
    else {
        puts("INVALID_MODE");
    }
    return 0;
}
